'use strict';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
const WORLDS=[{name:'햇살 과수원',sky:'#deeee7',items:[['apple','사과','🍎'],['banana','바나나','🍌'],['orange','오렌지','🍊']]},{name:'친구들의 숲',sky:'#e0ede3',items:[['cat','고양이','🐱'],['dog','강아지','🐶'],['rabbit','토끼','🐰']]},{name:'무지개 언덕',sky:'#e5e8f4',items:[['red','빨강','🔴'],['blue','파랑','🔵'],['yellow','노랑','🟡']]}];
let world=0,step=0,running=false,paused=false,muted=false,completed=false,cam=0,time=0,last=0,toast='',toastUntil=0;
let player={x:90,y:340,vy:0,grounded:false},keys={},collected=new Set(),particles=[];
let saved={};try{saved=JSON.parse(localStorage.getItem('eggQuestProgress')||'{}')}catch{}
const platforms=[{x:0,y:412,w:2000,h:90},{x:310,y:320,w:160,h:24},{x:690,y:302,w:160,h:24},{x:1070,y:320,w:160,h:24}];
const pickups=()=>WORLDS[world].items.map((item,i)=>({item,x:390+i*380,y:265,index:i}));
function speak(word){if(muted||!('speechSynthesis'in window))return; window.speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(word);u.lang='en-US';u.rate=.72;window.speechSynthesis.speak(u)}
function updateUI(){const item=WORLDS[world].items[Math.min(step,2)];$('worldName').textContent=`0${world+1} / ${WORLDS[world].name}`;$('target').textContent=item[0]+' ';const s=document.createElement('span');s.textContent=item[1];$('target').append(s);$('missionLabel').textContent=completed?'모든 단어를 찾았어요!':'듣고 알맞은 그림을 찾아요';$('count').textContent=`${step} / 3 발견`;$('bar').style.width=step/3*100+'%';$('stars').textContent='★'.repeat(step)+'☆'.repeat(3-step);document.querySelectorAll('.world').forEach((b,i)=>{b.classList.toggle('selected',i===world);b.setAttribute('aria-pressed',String(i===world));b.querySelector('.world-status').textContent=i===world?'선택됨':saved[i]?'★ ★ ★':'→'})}
function reset(start=false){step=0;collected.clear();particles=[];player={x:90,y:340,vy:0,grounded:false};cam=0;completed=false;paused=false;running=start;keys={};$('startPanel').classList.toggle('hidden',start);$('finishPanel').classList.add('hidden');$('pause').disabled=!start;$('pause').textContent='Ⅱ 쉬기';updateUI();if(start)speak(WORLDS[world].items[0][0])}
function start(){reset(true)}
function complete(){completed=true;running=false;keys={};saved[world]=true;try{localStorage.setItem('eggQuestProgress',JSON.stringify(saved))}catch{}updateUI();$('pause').disabled=true;const panel=$('finishPanel');panel.replaceChildren();const stars=document.createElement('div');stars.textContent='⭐ ⭐ ⭐';stars.style.fontSize='36px';const title=document.createElement('h2');title.textContent='멋져요! 모험을 마쳤어요';const p=document.createElement('p');p.textContent=WORLDS[world].items.map(x=>x[0]).join(' · ');const btn=document.createElement('button');btn.className='primary';btn.textContent=world<2?'다음 월드로 →':'다시 모험하기 ↻';btn.onclick=()=>{world=(world+1)%3;start()};panel.append(stars,title,p,btn);panel.classList.remove('hidden');speak('Great job!')}
function jump(){if(running&&!paused&&player.grounded){player.vy=-610;player.grounded=false}}
$('start').onclick=start;$('restart').onclick=()=>reset(true);$('listen').onclick=()=>speak(WORLDS[world].items[Math.min(step,2)][0]);$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'◖ 소리 꺼짐':'◖ 소리 켜짐';$('sound').setAttribute('aria-pressed',String(!muted));if(muted&&window.speechSynthesis)window.speechSynthesis.cancel()};
function togglePause(){if(!running)return;paused=!paused;keys={};$('pause').textContent=paused?'▶ 계속하기':'Ⅱ 쉬기'}$('pause').onclick=togglePause;
$('guide').onclick=()=>{if(running&&!paused)togglePause();$('help').showModal()};$('closeHelp').onclick=()=>$('help').close();
document.querySelectorAll('.world').forEach(b=>b.onclick=()=>{world=Number(b.dataset.world);reset()});
window.addEventListener('keydown',e=>{if($('help').open)return;if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code)){e.preventDefault();keys[e.code]=true;if(e.code==='Space'||e.code==='ArrowUp')jump()}});window.addEventListener('keyup',e=>{keys[e.code]=false});window.addEventListener('blur',()=>{keys={};if(running&&!paused)togglePause()});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true;if(b.dataset.key==='Space')jump()});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys[b.dataset.key]=false)});
function round(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function text(t,x,y,size,color,align='center'){ctx.fillStyle=color;ctx.font=`600 ${size}px "Noto Sans KR",sans-serif`;ctx.textAlign=align;ctx.fillText(t,x,y)}
function cloud(x,y,s){ellipse(x,y,44*s,17*s,'#ffffffb8');ellipse(x-20*s,y-9*s,23*s,21*s,'#ffffffb8');ellipse(x+12*s,y-17*s,28*s,25*s,'#ffffffb8')}
function tree(x,y,s){round(x-6*s,y-10*s,12*s,100*s,4,'#b6aa79');ellipse(x,y-14*s,44*s,60*s,'#9eb787');ellipse(x-20*s,y+6*s,29*s,35*s,'#9eb787');ellipse(x+25*s,y,25*s,37*s,'#a9bf91')}
function chick(x,y){ellipse(x,y+31,25,7,'#48684b22');ellipse(x-10,y+27,8,4,'#d59c42');ellipse(x+12,y+27,8,4,'#d59c42');ellipse(x,y,24,29,'#fff8d8');ellipse(x,y+6,21,20,'#f7d36b');ellipse(x,y-9,22,20,'#fff8d8');ellipse(x-7,y-12,2.6,3.2,'#334537');ellipse(x+8,y-12,2.6,3.2,'#334537');ellipse(x-13,y-4,4,2.4,'#efb1a0');ellipse(x+14,y-4,4,2.4,'#efb1a0');ctx.fillStyle='#e6aa43';ctx.beginPath();ctx.moveTo(x-4,y-5);ctx.lineTo(x+5,y-5);ctx.lineTo(x,y+1);ctx.fill();round(x-21,y-35,42,8,4,'#6b8c56');ellipse(x+1,y-36,16,8,'#6b8c56');ellipse(x-20,y+8,7,12,'#f2ce6a')}
function draw(){let W=1200,H=480;ctx.clearRect(0,0,W,H);ctx.fillStyle=WORLDS[world].sky;ctx.fillRect(0,0,W,H);ellipse(1035-cam*.1,78,39,39,'#f9e5a1');for(let i=0;i<5;i++)cloud(i*355+90-cam*.18,80+(i%2)*37,.8);ellipse(200-cam*.2,453,430,230,'#b9ceac');ellipse(1050-cam*.2,438,500,250,'#c5d7b5');ellipse(570-cam*.3,460,350,165,'#a9c39d');
ctx.save();ctx.translate(-cam,0);for(let i=0;i<8;i++)tree(140+i*270,310+(i%2)*30,.7+(i%3)*.15);
for(const p of platforms){round(p.x,p.y,p.w,p.h,8,'#d7c293');round(p.x,p.y,p.w,11,6,'#7fa56b');if(p.y===412){ctx.fillStyle='#c6b384';for(let i=0;i<50;i++)ctx.fillRect(i*45+15,442+(i%2)*20,5,4)}}
for(let i=0;i<28;i++){const x=i*69+25;text(i%3===0?'✿':'⌇',x,408,15,i%3===0?'#f6edbc':'#729a62')}
for(const p of pickups()){if(collected.has(p.index))continue;const bob=Math.sin(time*2+p.index)*5;ellipse(p.x,p.y+38,26,5,'#61794b22');round(p.x-35,p.y-39+bob,70,74,19,'#fffdf0');ctx.strokeStyle=p.index===step?'#d9ac52':'#ffffff';ctx.lineWidth=3;ctx.strokeRect(p.x-32,p.y-36+bob,64,68);text(p.item[2],p.x,p.y+10+bob,37,'#263d32');text('?',p.x,p.y-55+bob,18,'#698251')}
round(1590,202,9,210,4,'#6b875a');ctx.fillStyle='#e9bc5b';ctx.beginPath();ctx.moveTo(1599,205);ctx.lineTo(1670,228);ctx.lineTo(1599,251);ctx.fill();text('GOAL',1595,190,12,'#5f7d52');chick(player.x,player.y);
for(const p of particles){ellipse(p.x,p.y,4,4,p.color)}ctx.restore();
if(toast&&time<toastUntil){round(380,27,440,46,23,'#fffdf1ee');text(toast,600,57,17,'#3d6442')}if(paused){ctx.fillStyle='#f9f8edbb';ctx.fillRect(0,0,W,H);text('잠깐 쉬어가요 ☁',600,220,30,'#426348');text('계속하기 버튼을 눌러주세요',600,257,16,'#6d8061')}
}
function physics(dt){const direction=Number(!!keys.ArrowRight)-Number(!!keys.ArrowLeft);player.x=Math.max(28,Math.min(1710,player.x+direction*250*dt));const oldBottom=player.y+29;player.vy+=1550*dt;player.y+=player.vy*dt;player.grounded=false;for(const p of platforms){if(player.vy>=0&&oldBottom<=p.y+2&&player.y+29>=p.y&&player.x+19>p.x&&player.x-19<p.x+p.w){player.y=p.y-29;player.vy=0;player.grounded=true}}
for(const p of pickups()){if(collected.has(p.index))continue;if(Math.abs(player.x-p.x)<48&&Math.abs(player.y-p.y)<59){if(p.index===step){collected.add(p.index);step++;toast='잘했어요! '+p.item[0]+' ✨';toastUntil=time+1.7;for(let i=0;i<20;i++)particles.push({x:p.x,y:p.y,vx:(Math.random()-.5)*180,vy:-Math.random()*200,color:['#edc267','#8cae6c','#f4f1dc'][i%3],life:1});updateUI();if(step===3){complete()}else{speak(WORLDS[world].items[step][0])}}else if(time>toastUntil){toast='다시 들어볼까요? '+WORLDS[world].items[step][0];toastUntil=time+1.5;speak(WORLDS[world].items[step][0])}}}
cam=Math.max(0,Math.min(600,player.x-360));for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=400*dt;p.life-=dt}particles=particles.filter(p=>p.life>0)}
function frame(now){const dt=Math.min((now-last)/1000,.035);last=now;time+=dt;if(running&&!paused)physics(dt);draw();requestAnimationFrame(frame)}
reset();requestAnimationFrame(frame);
